void bufferMemoryBarrier(
    VkCommandBuffer commandBuffer,
    VkPipelineStageFlags2 srcStage,
    VkAccessFlags2 srcAccess,
    VkPipelineStageFlags2 dstStage,
    VkAccessFlags2 dstAccess,
    VkBuffer buffer,
    VkDeviceSize size,
    VkDeviceSize offset = 0) {
    VkBufferMemoryBarrier2 barrier{};
    barrier.sType = VK_STRUCTURE_TYPE_BUFFER_MEMORY_BARRIER_2;
    barrier.srcStageMask = srcStage;
    barrier.srcAccessMask = srcAccess;
    barrier.dstStageMask = dstStage;
    barrier.dstAccessMask = dstAccess;
    barrier.srcQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
    barrier.dstQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
    barrier.buffer = buffer;
    barrier.offset = offset;
    barrier.size = size;

    VkDependencyInfo dependency{};
    dependency.sType = VK_STRUCTURE_TYPE_DEPENDENCY_INFO;
    dependency.bufferMemoryBarrierCount = 1;
    dependency.pBufferMemoryBarriers = &barrier;
    recordManualBarrierEscape("PathTracerRenderer", "bufferMemoryBarrier", dependency);
    vkCmdPipelineBarrier2(commandBuffer, &dependency);
}

float halton(uint32_t index, uint32_t base) {
    float result = 0.0f;
    float fraction = 1.0f / static_cast<float>(base);
    while (index > 0) {
        result += fraction * static_cast<float>(index % base);
        index /= base;
        fraction /= static_cast<float>(base);
    }
    return result;
}

std::array<float, 16> rowMajorMatrixArray(const glm::mat4& matrix) {
    std::array<float, 16> result{};
    for (uint32_t row = 0; row < 4; ++row) {
        for (uint32_t column = 0; column < 4; ++column) {
            result[row * 4u + column] = matrix[column][row];
        }
    }
    return result;
}

StreamlineDlssQualityMode selectStreamlineDlssQualityMode(VkExtent2D renderExtent, VkExtent2D outputExtent) {
    if (renderExtent.width == 0u || renderExtent.height == 0u || outputExtent.width == 0u || outputExtent.height == 0u) {
        return StreamlineDlssQualityMode::Balanced;
    }
    const float scaleX = static_cast<float>(renderExtent.width) / static_cast<float>(outputExtent.width);
    const float scaleY = static_cast<float>(renderExtent.height) / static_cast<float>(outputExtent.height);
    const float scale = std::min(scaleX, scaleY);
    if (scale >= 0.98f) {
        return StreamlineDlssQualityMode::Dlaa;
    }
    if (scale >= 0.67f) {
        return StreamlineDlssQualityMode::Quality;
    }
    if (scale >= 0.58f) {
        return StreamlineDlssQualityMode::Balanced;
    }
    if (scale >= 0.45f) {
        return StreamlineDlssQualityMode::Performance;
    }
    return StreamlineDlssQualityMode::UltraPerformance;
}

std::filesystem::path glslangPath() {
#if defined(_MSC_VER)
    char* sdk = nullptr;
    size_t sdkLength = 0;
    _dupenv_s(&sdk, &sdkLength, "VULKAN_SDK");
    if (sdk == nullptr) {
        throw std::runtime_error("VULKAN_SDK is not set; cannot locate glslangValidator");
    }
    std::filesystem::path result = std::filesystem::path(sdk) / "Bin" / "glslangValidator.exe";
    std::free(sdk);
    return result;
#else
    const char* sdk = std::getenv("VULKAN_SDK");
    if (sdk == nullptr) {
        throw std::runtime_error("VULKAN_SDK is not set; cannot locate glslangValidator");
    }
    return std::filesystem::path(sdk) / "Bin" / "glslangValidator";
#endif
}

VkDescriptorSetLayoutBinding descriptorBinding(uint32_t binding, VkDescriptorType type, VkShaderStageFlags stages, uint32_t count = 1) {
    VkDescriptorSetLayoutBinding result{};
    result.binding = binding;
    result.descriptorType = type;
    result.descriptorCount = count;
    result.stageFlags = stages;
    return result;
}

void addOrUpdateDescriptorBinding(
    std::vector<VkDescriptorSetLayoutBinding>& bindings,
    VkDescriptorSetLayoutBinding binding) {
    auto found = std::find_if(bindings.begin(), bindings.end(), [binding](const VkDescriptorSetLayoutBinding& candidate) {
        return candidate.binding == binding.binding;
    });
    if (found == bindings.end()) {
        bindings.push_back(binding);
        return;
    }
    found->stageFlags |= binding.stageFlags;
}

